// ---- ToTest effects (fx_extra.cpp): XK = knob, XKL = logarithmic knob, XC = choice menu ----
#define XK(key, label, unit, mn, mx, st, df, hint)	{key, label, unit, mn, mx, st, df, 0, 0, 0, 0, 0, hint}
#define XKL(key, label, unit, mn, mx, st, df, hint)	{key, label, unit, mn, mx, st, df, 0, 1, 0, 0, 0, hint}
#define XC(key, label, mx, df, en, hint)		{key, label, "", 0.0f, mx, 1.0f, df, 1, 0, 0, en, (u8) (mx + 1), hint}
