#define FX_DEF_COUNT	((unsigned) (sizeof g_FxDefs / sizeof g_FxDefs[0]))

// an effect's parameters must fit in the block's vector
typedef char FxMaxParamsOk[FX_GEN_MAX_PARAMS <= FX_MAX_P ? 1 : -1];

static inline const TFxDef *FxDefByType (unsigned nType)
{
	for (unsigned i = 0; i < FX_DEF_COUNT; i++)
	{
		if (g_FxDefs[i].Type == nType)
		{
			return &g_FxDefs[i];
		}
	}
	return 0;
}

